/* Application adaptation of React Bits, David Haz, pinned source and full license in NOTICE.md.
 * Retains Masonry gridOf/place/layoutOf and DomeGallery buildItems/base rotation algorithms.
 * Browser gestures, RAF physics and lightbox DOM are replaced by the project's deterministic clock.
 */
export type Item={id:string;img:string;width?:number;height?:number;span?:number};
type Grid={count:number;size:number};type Measured=Record<string,number>;
const keyOf=(item:Item)=>String(item.id);
const aspectOf=(item:Item,measured:Measured)=>{const width=item.width??0,height=item.height??0;if(width>0&&height>0)return height/width;if(measured[keyOf(item)])return measured[keyOf(item)];if(height>0)return height/600;return 1};
const gridOf=(width:number,columns:'auto'|number,columnWidth:number,gap:number):Grid=>{const fixed=Number(columns);const count=columns!=='auto'&&fixed>0?Math.max(1,Math.round(fixed)):Math.max(1,Math.floor((width+gap)/(Math.max(40,columnWidth)+gap)));return {count,size:Math.max(1,(width-gap*(count-1))/count)}};
const place=(heights:number[],item:Item,grid:Grid,gap:number,measured:Measured,commit:boolean)=>{const {count,size}=grid;const span=Math.min(count,Math.max(1,Math.round(item.span||1)));let column=0,top=Infinity;for(let start=0;start<=count-span;start++){let y=0;for(let k=start;k<start+span;k++)y=Math.max(y,heights[k]);if(y<top-.5){top=y;column=start}}const w=size*span+gap*(span-1),h=Math.max(1,w*aspectOf(item,measured));if(commit)for(let k=column;k<column+span;k++)heights[k]=top+h+gap;return {x:Math.round(column*(size+gap)),y:Math.round(top),w,h}};
export const layoutOf=(list:Item[],width:number,columns:'auto'|number,columnWidth:number,gap:number,measured:Measured={})=>{const grid=gridOf(width,columns,columnWidth,gap),heights=new Array(grid.count).fill(0);const tiles=list.map(item=>({item,id:keyOf(item),...place(heights,item,grid,gap,measured,true)}));return {tiles,height:Math.max(0,Math.max(...heights)-gap)}};
export type ImageItem={src:string;alt:string};
export function buildItems(pool:ImageItem[],seg:number){const xCols=Array.from({length:seg},(_,i)=>-37+i*2),evenYs=[-4,-2,0,2,4],oddYs=[-3,-1,1,3,5];const coords=xCols.flatMap((x,c)=>(c%2===0?evenYs:oddYs).map(y=>({x,y,sizeX:2,sizeY:2})));const totalSlots=coords.length;if(pool.length===0)return coords.map(c=>({...c,src:'',alt:''}));const normalizedImages=pool.map(image=>({src:image.src||'',alt:image.alt||''}));const usedImages=Array.from({length:totalSlots},(_,i)=>normalizedImages[i%normalizedImages.length]);for(let i=1;i<usedImages.length;i++){if(usedImages[i].src===usedImages[i-1].src){for(let j=i+1;j<usedImages.length;j++){if(usedImages[j].src!==usedImages[i].src){const tmp=usedImages[i];usedImages[i]=usedImages[j];usedImages[j]=tmp;break}}}}return coords.map((c,i)=>({...c,src:usedImages[i].src,alt:usedImages[i].alt}))}
export function computeItemBaseRotation(offsetX:number,offsetY:number,sizeX:number,sizeY:number,segments:number){const unit=360/segments/2;return {rotateY:unit*(offsetX+(sizeX-1)/2),rotateX:unit*(offsetY-(sizeY-1)/2)}}
